const items = $input.all();

let formattedData = "";
let count = 0;
const MAX_ITEMS = 12;

for (const item of items) {
  const data = item.json;

  // Tavily results
  if (Array.isArray(data.results)) {
    for (const result of data.results) {
      if (count >= MAX_ITEMS) break;

      formattedData += `SOURCE: Web
TITLE: ${result.title || "No title"}
CONTENT: ${(result.content || "").slice(0, 400)}
URL: ${result.url || "No URL"}
-------------------------
`;

      count++;
    }
  }

  // Hacker News results
  if (Array.isArray(data.hits)) {
    for (const story of data.hits) {
      if (count >= MAX_ITEMS) break;

      formattedData += `SOURCE: HackerNews
TITLE: ${story.title || "No title"}
POINTS: ${story.points || 0}
COMMENTS: ${story.num_comments || 0}
URL: ${story.url || `https://news.ycombinator.com/item?id=${story.objectID}`}
-------------------------
`;

      count++;
    }
  }

  if (count >= MAX_ITEMS) break;
}

return [
  {
    json: {
      formattedData,
      sourceCount: count
    }
  }
];

const input = $input.first().json;

// Get AI output
const text =
  input.text ||
  input.output ||
  input.response ||
  "";

const lines = text.split("\n");

let stories = [];
let current = {};

for (const line of lines) {
  const trimmed = line.trim();

  if (/^\d+\)/.test(trimmed)) {
    if (Object.keys(current).length > 0) {
      stories.push(current);
    }

    current = {
      headline: trimmed.replace(/^\d+\)\s*/, "")
    };
  } else if (trimmed.startsWith("HEADLINE:")) {
    current.headline = trimmed.replace("HEADLINE:", "").trim();
  } else if (trimmed.startsWith("WTF SCORE:")) {
    current.score = trimmed.replace("WTF SCORE:", "").trim();
  } else if (trimmed.startsWith("SOURCE:")) {
    current.source = trimmed.replace("SOURCE:", "").trim();
  } else if (trimmed.startsWith("WHY:")) {
    current.why = trimmed.replace("WHY:", "").trim();
  } else if (trimmed.startsWith("IDEA:")) {
    current.idea = trimmed.replace("IDEA:", "").trim();
  } else if (trimmed.startsWith("URL:")) {
    current.url = trimmed.replace("URL:", "").trim();
  }
}

if (Object.keys(current).length > 0) {
  stories.push(current);
}

// Remove incomplete/duplicate stories
stories = stories
  .filter(story => story.headline && story.url)
  .filter(
    (story, index, self) =>
      index === self.findIndex(
        s => s.url === story.url
      )
  );

let storyHTML = "";

stories.forEach((story, index) => {
  const score = parseInt(story.score) || 0;

  storyHTML += `
  <div style="
    background:#111111;
    border:1px solid #292929;
    border-radius:12px;
    padding:24px;
    margin-bottom:20px;
  ">

    <div style="
      font-size:13px;
      color:#888888;
      margin-bottom:10px;
    ">
      #${index + 1} &nbsp; • &nbsp; ${story.source || "AI NEWS"}
    </div>

    <div style="
      font-size:22px;
      font-weight:bold;
      color:#ffffff;
      line-height:1.4;
      margin-bottom:12px;
    ">
      ${story.headline}
    </div>

    <div style="
      display:inline-block;
      background:#1f1f1f;
      border:1px solid #3a3a3a;
      border-radius:20px;
      padding:6px 12px;
      color:#ffffff;
      font-size:13px;
      margin-bottom:16px;
    ">
      WTF SCORE: ${score}/10
    </div>

    <div style="
      color:#cccccc;
      font-size:15px;
      line-height:1.6;
      margin-bottom:14px;
    ">
      <strong style="color:#ffffff;">Why it matters:</strong><br>
      ${story.why || "Interesting AI development."}
    </div>

    <div style="
      background:#181818;
      border-left:3px solid #ffffff;
      padding:12px 15px;
      margin-bottom:18px;
      color:#bbbbbb;
      font-size:14px;
      line-height:1.5;
    ">
      <strong style="color:#ffffff;">Content idea:</strong><br>
      ${story.idea || "Create a short post explaining this development."}
    </div>

    <a href="${story.url}"
       style="
         display:inline-block;
         background:#ffffff;
         color:#000000;
         text-decoration:none;
         padding:10px 18px;
         border-radius:7px;
         font-weight:bold;
         font-size:14px;
       ">
       Read Story →
    </a>

  </div>
  `;
});

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
</head>

<body style="
  margin:0;
  padding:0;
  background:#050505;
  font-family:Arial,Helvetica,sans-serif;
">

<table width="100%" cellpadding="0" cellspacing="0"
       style="background:#050505;">

<tr>
<td align="center">

<table width="650" cellpadding="0" cellspacing="0"
       style="max-width:650px;">

<tr>
<td style="padding:40px 20px 20px 20px;">

  <div style="
    color:#ffffff;
    font-size:32px;
    font-weight:bold;
    margin-bottom:8px;
  ">
    WTF AI
  </div>

  <div style="
    color:#888888;
    font-size:15px;
    margin-bottom:30px;
  ">
    The AI stories that make you say...
    <strong style="color:#ffffff;">Wait, WTF?</strong>
  </div>

  ${storyHTML}

  <div style="
    text-align:center;
    color:#666666;
    font-size:12px;
    padding:25px 10px 40px 10px;
  ">
    Generated automatically with n8n + Ollama
    <br>
    AI News Digest
  </div>

</td>
</tr>

</table>

</td>
</tr>

</table>

</body>
</html>
`;

return [
  {
    json: {
      subject: `🔥 WTF AI — ${stories.length} AI Stories You Need to See`,
      html,
      storyCount: stories.length
    }
  }
];
